                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1 * globalScale;
                  ctx.strokeStyle = isJIOverride ? 'rgba(255,255,255,0.4)' : `rgba(255,255,255,${0.8 * limitOpacity})`;
